// Single source of truth for XP, levels, credits and unlocks.
const input = $('Start').first().json;
const found = $input.first().json;
const now = Date.now();
const today = new Date(now).toISOString().slice(0, 10);
const yesterday = new Date(now - 864e5).toISOString().slice(0, 10);

const LEVELS = [
  { level: 1, title: 'Intern', xp: 0, credits: 0 },
  { level: 2, title: 'Junior Creative', xp: 100, credits: 1 },
  { level: 3, title: 'Art Director', xp: 250, credits: 1 },
  { level: 4, title: 'Creative Director', xp: 500, credits: 2 },
  { level: 5, title: 'Chief Creative', xp: 1000, credits: 3 },
];
const FORMATS = { square: 1, portrait: 2, landscape: 2 };
const STYLES = { auto: 1, 'luxe-dark': 3, sunlit: 3, 'minimal-studio': 3, nature: 3, neon: 3 };
const DIRECTION_LEVEL = 4;
const DAILY_REWARDED = 20;
const DAILY_CAP = 60;

const num = (v) => Number(v ?? 0) || 0;
const u = {
  uid: input.uid,
  email: found.email ?? '',
  emailVerified: found.emailVerified === true,
  codeHash: found.codeHash ?? '',
  codeExpires: num(found.codeExpires),
  codeTries: num(found.codeTries),
  xp: num(found.xp),
  credits: num(found.credits),
  level: num(found.level) || 1,
  messages: num(found.messages),
  ads: num(found.ads),
  rewardedToday: num(found.rewardedToday),
  sentToday: num(found.sentToday),
  activeDate: found.activeDate ?? '',
  streak: num(found.streak),
  lastText: found.lastText ?? '',
  photoRewarded: found.photoRewarded ?? '',
};

let ok = true, status = 200, error = null, gained = 0, mergedUid = null;
const fail = (code, message) => { ok = false; status = code; error = message; };
const levelFor = (xp) => LEVELS.filter((l) => xp >= l.xp).pop();

switch (input.event) {
  case 'message': {
    if (u.activeDate !== today) {
      u.streak = u.activeDate === yesterday ? u.streak + 1 : 1;
      u.activeDate = today;
      u.sentToday = 0;
      u.rewardedToday = 0;
      gained += 15 * Math.min(u.streak, 5);
    }
    if (u.sentToday >= DAILY_CAP) {
      fail(429, "You've reached today's chat limit. Come back tomorrow.");
      break;
    }
    u.sentToday += 1;
    u.messages += 1;
    const text = String(input.text ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
    if (text.split(' ').length >= 3 && text !== u.lastText && u.rewardedToday < DAILY_REWARDED) {
      gained += 10;
      u.rewardedToday += 1;
    }
    u.lastText = text.slice(0, 500);
    if (input.photoKey && input.photoKey !== u.photoRewarded && u.rewardedToday < DAILY_REWARDED) {
      gained += 30;
      u.rewardedToday += 1;
      u.photoRewarded = input.photoKey;
    }
    break;
  }
  case 'setCode': {
    if (u.emailVerified) fail(400, 'Your email is already verified.');
    else if (u.codeExpires - 9 * 60e3 > now) fail(429, 'Wait a minute before requesting another code.');
    else {
      u.email = input.email;
      u.codeHash = input.codeHash;
      u.codeExpires = now + 10 * 60e3;
      u.codeTries = 0;
    }
    break;
  }
  case 'verify': {
    if (!u.codeHash || now > u.codeExpires) fail(400, 'That code has expired. Request a new one.');
    else if (input.codeHash !== u.codeHash) {
      u.codeTries += 1;
      if (u.codeTries >= 5) u.codeHash = '';
      fail(400, u.codeHash ? "That code isn't right." : 'Too many attempts. Request a new code.');
    } else {
      u.codeHash = '';
      if (input.ownerUid && input.ownerUid !== u.uid) mergedUid = input.ownerUid;
      else if (!u.emailVerified) {
        u.emailVerified = true;
        u.credits += 1;
        gained += 100;
      }
    }
    break;
  }
  case 'spend': {
    const level = levelFor(u.xp).level;
    const aspect = input.aspect || 'square';
    const style = input.style || 'auto';
    if (!u.emailVerified) fail(403, 'Verify your email to start shooting.');
    else if (!(aspect in FORMATS) || !(style in STYLES)) fail(400, 'Unknown format or style.');
    else if (FORMATS[aspect] > level) fail(403, 'Reach level ' + FORMATS[aspect] + ' to unlock this format.');
    else if (STYLES[style] > level) fail(403, 'Reach level ' + STYLES[style] + ' to unlock scene styles.');
    else if (input.direction && level < DIRECTION_LEVEL) fail(403, 'Reach level ' + DIRECTION_LEVEL + ' to add art direction.');
    else if (u.credits < 1) fail(402, 'No shoots left. Keep chatting to earn your next one.');
    else u.credits -= 1;
    break;
  }
  case 'ad':
    u.ads += 1;
    gained += 50;
    break;
  case 'refund':
    u.credits += 1;
    break;
}

u.xp += gained;
const before = u.level;
const after = Math.max(before, levelFor(u.xp).level);
for (let l = before + 1; l <= after; l++) u.credits += LEVELS[l - 1].credits;
u.level = after;

const current = LEVELS[after - 1];
const next = LEVELS[after] ?? null;
const progress = {
  level: after,
  title: current.title,
  xp: u.xp,
  levelXp: current.xp,
  nextXp: next ? next.xp : null,
  nextTitle: next ? next.title : null,
  credits: u.credits,
  messages: u.messages,
  ads: u.ads,
  streak: u.streak,
  email: u.emailVerified ? u.email : null,
  unlocks: {
    formats: Object.keys(FORMATS).filter((k) => FORMATS[k] <= after),
    styles: Object.keys(STYLES).filter((k) => STYLES[k] <= after),
    direction: after >= DIRECTION_LEVEL,
    signature: after >= 5,
  },
};

return [{ json: { ok, status, error, gained, leveledUp: after > before, mergedUid, progress, user: u } }];

// Return the outcome without internal fields like the code hash.
const { user, ...result } = $('Apply rules').first().json;
return [{ json: result }];
